/* master: partition, dispatch, join, combine */
for (i = 0; i < NWORKERS; i++) pthread_create(&tid[i], NULL, worker, &ctx[i]);
for (int lo = 0; lo < n; lo += chunk) {                 /* partition */
    pthread_mutex_lock(&m);
    queue_push(&q, (struct job){lo, min(lo + chunk, n)});
    pthread_cond_signal(&has_work);                     /* dispatch */
    pthread_mutex_unlock(&m);
}
pthread_mutex_lock(&m); q.done = 1; pthread_cond_broadcast(&has_work);
pthread_mutex_unlock(&m);
for (i = 0; i < NWORKERS; i++) pthread_join(tid[i], NULL);   /* join */
total = reduce(partial, NWORKERS);                           /* combine */
